\sigma_{zz}=\frac{\mu}{k}\big[\Phi'''-3k^{2}\Phi'\big]\cos kx
          =-P+2\mu\partial_{z}u_{z},
\end{equation*}
and on the regular biharmonic

$\Phi(z)=(A+Bz)e^{kz}+(C+Dz)e^{-kz}$.
In the time independent material limit the locked deflected surface is

$u_{x}(0)=0$,  $\dot e=0$ i.e. $u_{z}(0)=0$,

$\Phi(0)=\Phi'(0)=0$,
$C=-A$, $D=-B-2kA$, and with $a=kh$

\begin{equation*}
\Phi(z)=A\big[\sinh kz-kz\cosh kz\big]+B z\sinh kz .
\end{equation*}
Then

\begin{equation*}
\Phi'''(0)=-4k^{3}A,\qquad 
\sigma_{zz}(0)=\frac{\mu}{k}\Phi'''(0)\cos kx ,
\end{equation*}
so that on the normalisation used in the statement

$\sigma_{zz}(0)=\rho g\,e(t)\cos kx$

\begin{equation*}
