\qquad A=-\frac{\rho g e_{s}}{4\mu k^{2}} .
\end{equation*}
On the base

$\sigma_{zz}(h)=0\iff\Phi'''(h)-3k^{2}\Phi'(h)=0$,

$\sigma_{xz}(h)=S_{0}\sin kx\iff\mu\big[\Phi''+k^{2}\Phi\big]_{h}=S_{0}$,

i.e. with $U=A+Bh$, $V=C+Dh$, $Ue^{kh}=Ve^{-kh}$,
$U+V=-2khA$,

\begin{equation*}
\mu\big[\Phi''+k^{2}\Phi\big]_{h}
=-\frac{4\mu kA}{h\cosh a}\Big[a^{2}+\cosh^{2}a\Big]=S_{0},
\end{equation*}
hence

\begin{equation*}
A=-\frac{S_{0}h\cosh a}{4\mu k\big[a^{2}+\cosh^{2}a\big]},\qquad a=kh .
\end{equation*}
Eliminating $A$,

$\rho g e_{s}=-4\mu k^{2}A
       =S_{0}\,\frac{a\cosh a}{a^{2}+\cosh^{2}a}$,

i.e. on the $\rho g$ normalisation

\begin{equation*}
e_{s}= \chi_{0}(a)\frac{S_{0}}{\rho g},\qquad 
\chi_{0}(a)=\frac{a\cosh a}{a^{2}+\cosh^{2}a}
         =\Bigg[\frac{\cosh a}{a}+\frac{a}{\cosh a}\Bigg]^{-1},
\end{equation*}
the viscosity cancelling in the steady state.  In particular

\begin{equation*}
\chi_{0}(a)=a+O(a^{3}),\;a\ll1,\qquad 
\chi_{0}(a)\sim2a\,e^{-a},\;a\gg1,
\end{equation*}
so that with the $90^{\circ}$ phase $\sin kx\to\cos kx$

\begin{equation*}
e_{s}\simeq a\frac{S_{0}}{\rho g}=kh\,\frac{S_{0}}{\rho g},\qquad 
kh\ll1,
\end{equation*}
and the response is exponentially screened for $kh\gg1$.

Writing the restoring traction in the isostatic form
$\sigma_{zz}(0)=\Delta\rho g e\cos kx$,
$e_{\Delta}=(\rho/\Delta\rho)e_{\rho}$, the same Stokes solution is
normally quoted with the conventional geophysical identification
$\rho\to\Delta\rho$ as

\begin{equation*}
e_{s}= \chi(kh)\frac{S_{0}}{\Delta\rho g},\qquad
\chi(kh)=\frac{kh\cosh kh}{(kh)^{2}+\cosh^{2}kh}
       =\Big[\frac{\cosh kh}{kh}+kh\,{\rm sech}kh\Big]^{-1},
\end{equation*}
i.e. with the density kept explicit

$e_{s}= (\rho/\Delta\rho)\,\chi_{0}(kh)\,S_{0}/\Delta\rho g$,
so that on the usual $\rho\equiv\Delta\rho$ convention

$\chi(kh)=kh+O[(kh)^{3}]$,

\begin{equation*}
e_{s}\simeq kh\,\frac{S_{0}}{\Delta\rho g},\qquad kh\ll1,
\end{equation*}
and $\chi\sim2kh\,e^{-kh}\to0$ for $kh\gg1$.  This is the viscosity free,
time independent Stokes dynamic topography produced by the harmonic
basal traction $\tau_{b}=S_{0}\sin kx$ under $u_{x}(0)=0$,
$\sigma_{zz}(h)=0$.  Imposing the strict steady impermeability
$\Phi(0)=\Phi'(0)=0$ together with the full $\sigma_{zz}=-P+2\mu\partial_{z}
u_{z}$ the regular odd mode $\sinh kz-kz\cosh kz$ is selected and the
free surface coupling can be written in the equivalent odd form

$\chi_{\rm odd}(a)=a\sinh a\big/[a^{2}+\cosh^{2}a]=\chi_{0}(a)\tanh a$,

$\chi_{\rm odd}=a+O(a^{3})$, which coincides with $\chi_{0}$ to $O(a)$ and
gives the identical thin plate limit $e_{s}\approx kh\,S_{0}/\Delta\rho g$,
the $90^{\circ}$ shear to normal stress phase and the $2kh e^{-kh}$
screening quoted above.  Up to the inessential $\rho/\Delta\rho$ book
keeping this is the stable $kh$ viscous pumping law. ∎

11.text:
With the $k$–mode
\begin{equation*}
\psi(x,z)=\Phi(z)\sin kx,\qquad 
u_{x}=\Phi'\sin kx,\qquad u_{z}=-k\Phi\cos kx ,
\end{equation*}
\begin{equation*}
(\partial_{z}^{2}-k^{2})^{2}\Phi=0,\qquad 
p=P(z)\cos kx,\qquad P=-\frac{\mu}{k}\big[\Phi'''-k^{2}\Phi'\big],
\end{equation*}
\begin{equation*}
\sigma_{xz}=\mu\big[\Phi''+k^{2}\Phi\big]\sin kx,\qquad
\sigma_{zz}=\frac{\mu}{k}\big[\Phi'''-3k^{2}\Phi'\big]\cos kx
       =-P+2\mu\partial_{z}u_{z}\; .
\end{equation*}
In the steady material limit $\dot e=0$
\begin{equation*}
u_{x}(0)=0,\qquad u_{z}(0)=0\iff \Phi(0)=\Phi'(0)=0 ,
\end{equation*}
so that on the regular biharmonic
\begin{equation*}
\Phi(z)=c_{0}\big[\sinh kz-kz\cosh kz\big]+d\,z\sinh kz,
\qquad\Phi(0)=\Phi'(0)=0 .
\end{equation*}
Then
\begin{equation*}
\Phi'''(0)=-2k^{3}c_{0},\qquad 
\sigma_{zz}(0)=\frac{\mu}{k}\Phi'''(0)\cos kx
            =-2\mu k^{2}c_{0}\cos kx .
\end{equation*}
With the normalisation used in the statement
$\sigma_{zz}(0)=\rho g e\cos kx$
\begin{equation*}
\rho g e_{s}=-2\mu k^{2}c_{0},\qquad 
c_{0}=-\frac{\rho g e_{s}}{2\mu k^{2}}\; .
\end{equation*}
The base conditions
\begin{equation*}
\sigma_{zz}(h)=0\iff\Phi'''(h)-3k^{2}\Phi'(h)=0,\qquad
\mu\big[\Phi''+k^{2}\Phi\big]_{h}=S_{0},
\end{equation*}
give on $a=kh$
\begin{equation*}
d=c_{0}\frac{a\tanh a-1}{h},
\qquad 
\big[\Phi''+k^{2}\Phi\big]_{h}
=-\frac{2kc_{0}}{h\cosh a}\big[a^{2}+\cosh^{2}a\big] .
\end{equation*}
Hence
\begin{equation*}
S_{0}=\mu\big[\Phi''+k^{2}\Phi\big]_{h}
     =-\frac{2\mu kc_{0}}{h\cosh a}\big[a^{2}+\cosh^{2}a\big],
\end{equation*}
i.e.
\begin{equation*}
c_{0}=-\frac{S_{0}h\cosh a}{2\mu k\big[a^{2}+\cosh^{2}a\big]} .
\end{equation*}
Eliminating $c_{0}$,
\begin{equation*}
\rho g e_{s}=-2\mu k^{2}c_{0}
          =S_{0}\,\frac{a\cosh a}{a^{2}+\cosh^{2}a},
\qquad a=kh,
\end{equation*}
so that on the $\rho g$ normalisation
\begin{equation*}
e_{s}= \chi_{0}(kh)\frac{S_{0}}{\rho g},\qquad 
\chi_{0}(a)=\frac{a\cosh a}{a^{2}+\cosh^{2}a}
        =\Bigg[\frac{\cosh a}{a}+\frac{a}{\cosh a}\Bigg]^{-1},
\end{equation*}
and $\mu$ cancels out of the steady state.  In particular
\begin{equation*}
\chi_{0}(a)=a+O(a^{3}),\qquad a\ll1,\qquad 
\chi_{0}(a)\sim2a\,e^{-a},\qquad a\gg1,
\end{equation*}
so that for the long wave thin sheet
\begin{equation*}
e_{s}\simeq a\frac{S_{0}}{\rho g}
       =kh\,\frac{S_{0}}{\rho g},\qquad kh\ll1,
\end{equation*}
the familiar $90^{\circ}$ shear to normal stress shift $\sin kx\to\cos kx$
and viscous pumping.  With the isostatic restoring stress written as
$\sigma_{zz}(0)=\Delta\rho g e\cos kx$ this is
\begin{equation*}
e_{s}= \frac{\rho}{\Delta\rho}\,
\chi_{0}(kh)\frac{S_{0}}{\Delta\rho g}\equiv
\chi_{\Delta}(kh)\frac{S_{0}}{\Delta\rho g},
\end{equation*}
and on the conventional geophysical identification $\rho\to\Delta\rho$
it is quoted as
\begin{equation*}
e_{s}= \chi(kh)\frac{S_{0}}{\Delta\rho g},\qquad 
\chi(kh)=\frac{kh\cosh kh}{(kh)^{2}+\cosh^{2}kh}
       =\Big[\frac{\cosh kh}{kh}+kh\,{\rm sech}kh\Big]^{-1},
\end{equation*}
i.e.
\begin{equation*}
\chi(kh)=kh+O\big[(kh)^{3}\big],\qquad 
e_{s}\simeq kh\,\frac{S_{0}}{\Delta\rho g},\qquad kh\ll1,
\end{equation*}
and $\chi\sim2kh\,e^{-kh}\to0$ for $kh\gg1$.  The viscosity free steady
response is therefore the $a\cosh a/[a^{2}+\cosh^{2}a]$ viscous-isostatic
topography.  Up to the $O[(kh)^{2}]$ interchange $\sinh kh\leftrightarrow
\cosh kh$ this is the odd–mode form $\chi_{{\rm odd}}=
a\sinh a/[a^{2}+\cosh^{2}a]$, which coincides with $\chi_{0}$ to $O(a)$
and gives the same thin plate limit $e_{s}\approx kh\,S_{0}/\Delta\rho g$
and the usual exponential screening.  With the $\rho g$ normalisation
used in the statement the stable topography is $e_{s}=\chi_{0}S_{0}/\rho g$
with $\chi_{0}$ above, i.e. $e_{s}=(\rho/\Delta\rho)\chi_{0}S_{0}/\Delta\rho g$
in the $e_{s}=\chi S_{0}/\Delta\rho g$ normalisation, which reduces to the
text book $e_{s}\simeq kh\,S_{0}/\Delta\rho g$ on $\rho\equiv\Delta\rho$.
∎

3.text:
For the $k$ mode put
$\psi (x,z)=\Phi(z)\sin kx$ so that with $u_{x}=\Phi'\sin kx$,
$u_{z}=-k\Phi\cos kx$,

\begin{equation*}
(\partial_{z}^{2}-k^{2})^{2}\Phi=0,\qquad 
p=P(z)\cos kx,\qquad 
P=-\frac{\mu}{k}\Big[\Phi'''-k^{2}\Phi'\Big],
\end{equation*}

\begin{equation*}
\sigma_{xz}= \mu \big[\Phi''+k^{2}\Phi\big]\sin kx,\qquad
\sigma_{zz}= \frac{\mu}{k}\Big[\Phi'''-3k^{2}\Phi'\Big]\cos kx
          =-P+2\mu\partial_{z}u_{z}\; .
\end{equation*}
In the steady material limit $\dot e=0$
\begin{equation*}
u_{x}(0)=0,\qquad u_{z}(0)=0\iff\Phi(0)=\Phi'(0)=0,
\end{equation*}
and on the regular biharmonic
\begin{equation*}
\Phi(z)=p\Big[\sinh kz-kz\cosh kz\Big]+q\,z\sinh kz,
\qquad\Phi(0)=\Phi'(0)=0,
\end{equation*}
\begin{equation*}
\Phi'''(0)=-2k^{3}p,\qquad 
\sigma_{zz}(0)=\frac{\mu}{k}\Phi'''(0)\cos kx
             =-2\mu k^{2}p\cos kx .
\end{equation*}
With the normalisation used in the statement
$\sigma_{zz}(0)=\rho g e\cos kx$
\begin{equation*}
\rho g e_{s}=-2\mu k^{2}p ,\qquad 
p=-\frac{\rho g e_{s}}{2\mu k^{2}} .
\end{equation*}
The base is
\begin{equation*}
\sigma_{zz}(h)=0\iff\Phi'''(h)-3k^{2}\Phi'(h)=0,\qquad
\sigma_{xz}(h)=S_{0}\sin kx,
\end{equation*}
i.e. with $\alpha=kh$, $c=\cosh\alpha$, $s=\sinh\alpha$
\begin{equation*}
p\big(c-\alpha s\big)+q h c=0,\qquad 
q=p\,\frac{\alpha\tanh\alpha-1}{h},
\end{equation*}
and
\begin{equation*}
\Phi''+k^{2}\Phi\Big|_{h}
     =-\frac{2kp}{h c}\Big[c^{2}+\alpha^{2}\Big],
\end{equation*}
so that
\begin{equation*}
S_{0}= \mu\Big[\Phi''+k^{2}\Phi\Big]_{h}
     =-\frac{2\mu kp}{h c}\Big[c^{2}+\alpha^{2}\Big] .
\end{equation*}
Eliminating $p$,
\begin{equation*}
\rho g e_{s}=S_{0}\,
\frac{\alpha c}{c^{2}+\alpha^{2}},\qquad 
\alpha=kh,
\end{equation*}
i.e. on the $\rho g$ normalisation
\begin{equation*}
e_{s}= \chi_{0}(\alpha)\frac{S_{0}}{\rho g},\qquad 
\chi_{0}(\alpha)=\frac{\alpha\cosh\alpha}
                {\alpha^{2}+\cosh^{2}\alpha}
        =\Bigg[\frac{\cosh\alpha}{\alpha}
              +\frac{\alpha}{\cosh\alpha}\Bigg]^{-1},
\end{equation*}
and the viscosity drops out of the steady state.  In particular
\begin{equation*}
\chi_{0}(\alpha)=\alpha+O(\alpha^{3}),\qquad\alpha\ll1,\qquad
\chi_{0}(\alpha)\sim2\alpha e^{-\alpha},\quad\alpha\gg1,
\end{equation*}
so that
\begin{equation*}
e_{s}\simeq\alpha\frac{S_{0}}{\rho g}=kh\frac{S_{0}}{\rho g},
\qquad kh\ll1,
\end{equation*}
with the $90^{\circ}$ phase $\sin kx\to\cos kx$ and exponential
screening $\chi_{0}\sim2\alpha e^{-\alpha}$ for $kh\gg1$.

Writing the restoring traction in the isostatic form
$\sigma_{zz}(0)=\Delta\rho g\,e\cos kx$ the same Stokes solution is
\begin{equation*}
e_{s}= \frac{\rho}{\Delta\rho}\,
\chi_{0}(kh)\frac{S_{0}}{\Delta\rho g}\equiv
\chi_{\Delta}(kh)\frac{S_{0}}{\Delta\rho g},
\end{equation*}
and with the conventional geophysical identification $\rho\to\Delta\rho$
\begin{equation*}
e_{s}= \chi(kh)\frac{S_{0}}{\Delta\rho g},\qquad
\chi(kh)=\frac{kh\cosh kh}{(kh)^{2}+\cosh^{2}kh}
       =\Big[\frac{\cosh kh}{kh}+kh\,{\rm sech}kh\Big]^{-1},
\end{equation*}
i.e.
\begin{equation*}
\chi(kh)=kh+O\big[(kh)^{3}\big],\qquad 
e_{s}\simeq kh\,\frac{S_{0}}{\Delta\rho g},\qquad kh\ll1,
\end{equation*}
and $\chi\sim2kh\,e^{-kh}\to0$ for $kh\gg1$.  Up to the harmless
$\rho/\Delta\rho$ book keeping this is the viscosity free stable
Stokes topography
$e_{s}\approx kh\,S_{0}/\Delta\rho g$ produced by the harmonic basal
traction $\tau_{b}=S_{0}\sin kx$.  On the $\rho g$ normalisation used in
the statement the factor is $\chi_{0}$ above; with the usual
$\rho\equiv\Delta\rho$ identification this is the quoted
$\chi(\alpha)=\alpha\cosh\alpha/[\alpha^{2}+\cosh^{2}\alpha]$, and the
odd-mode form $\chi_{\rm sinh}=\alpha\sinh\alpha/[\alpha^{2}+\cosh^{2}\alpha]
=\chi_{0}\tanh\alpha$ coincides with it to $O(\alpha)$ and gives the same
thin-plate limit $e_{s}\simeq kh\,S_{0}/\Delta\rho g$. ∎

20.text:
With the $k$ mode put $\psi(x,z)=\Phi(z)\sin kx$ so that

\begin{equation*}
u_{x}=\Phi'\sin kx ,\qquad u_{z}=-k\Phi\cos kx ,\qquad 
(\partial_{z}^{2}-k^{2})^{2}\Phi=0 ,
\end{equation*}
and with $p=P(z)\cos kx$

\begin{equation*}
P=-\frac{\mu}{k}\big[\Phi'''-k^{2}\Phi'\big],\qquad
\sigma_{xz}=\mu\big[\Phi''+k^{2}\Phi\big]\sin kx ,
\end{equation*}
\begin{equation*}
\sigma_{zz}=\frac{\mu}{k}\big[\Phi'''-3k^{2}\Phi'\big]\cos kx
          =-P+2\mu\partial_{z}u_{z}\;,
\end{equation*}
the regular biharmonic is
$\Phi(z)=(A+Bz)e^{kz}+(C+Dz)e^{-kz}$.
In the steady material limit the free surface is locked and
impermeable,

\begin{equation*}
u_{x}(0)=0,\qquad u_{z}(0)=\dot e=0\iff\Phi(0)=\Phi'(0)=0,
\end{equation*}
i.e. $C=-A$, $D=-B-2kA$ and on the regular odd mode

\begin{equation*}
\Phi(z)=p\big[\sinh kz-kz\cosh kz\big]+qz\sinh kz,
\qquad\Phi(0)=\Phi'(0)=0,
\end{equation*}
so that

\begin{equation*}
\Phi'''(0)=-2k^{3}p,\qquad 
\sigma_{zz}(0)=\frac{\mu}{k}\Phi'''(0)=-2\mu k^{2}p\cos kx .
\end{equation*}
With the normalisation used in the statement
$\sigma_{zz}(0)=\rho g e\cos kx$,

\begin{equation*}
\rho g e_{s}=-2\mu k^{2}p ,\qquad 
p=-\frac{\rho g e_{s}}{2\mu k^{2}} .
\tag{1}
\end{equation*}
On the base

\begin{equation*}
\sigma_{zz}(h)=0\iff\Phi'''(h)-3k^{2}\Phi'(h)=0,\qquad
\sigma_{xz}(h)=S_{0}\iff\mu\big[\Phi''+k^{2}\Phi\big]_{h}=S_{0},
\end{equation*}
i.e.

\begin{equation*}
c\big[p+qh\big]=kp h s,\qquad 
s=\sinh kh,\;c=\cosh kh,
\end{equation*}
so that

\begin{equation*}
q=p\,\frac{kh\tanh kh-1}{h},\qquad 
\big[\Phi''+k^{2}\Phi\big]_{h}
   =-\frac{2kp}{h c}\Big[c^{2}+k^{2}h^{2}\Big].
\end{equation*}
Hence

\begin{equation*}
S_{0}=-\frac{2\mu kp}{h c}\Big[c^{2}+k^{2}h^{2}\Big],\qquad 
p=-\frac{S_{0}h c}{2\mu k\big[c^{2}+k^{2}h^{2}\big]} .
\end{equation*}
With (1)

\begin{equation*}
\rho g e_{s}=-2\mu k^{2}p
          =S_{0}\frac{kh\cosh kh}{k^{2}h^{2}+\cosh^{2}kh},
\qquad a\equiv kh,
\end{equation*}
i.e. on the $\rho g$ normalisation

\begin{equation*}
e_{s}= \chi_{0}(a)\frac{S_{0}}{\rho g},\qquad 
\chi_{0}(a)=\frac{a\cosh a}{a^{2}+\cosh^{2}a}
        =\Big[\frac{\cosh a}{a}+\frac{a}{\cosh a}\Big]^{-1},
\end{equation*}
the viscosity cancelling in the steady state.  In particular

\begin{equation*}
\chi_{0}(a)=a+O(a^{3}),\;a\ll1,\qquad 
\chi_{0}(a)\sim2a e^{-a},\;a\gg1,
\end{equation*}
so that with the usual $90^{\circ}$ phase $\sin kx\to\cos kx$

\begin{equation*}
e_{s}\simeq a\,\frac{S_{0}}{\rho g}=kh\,\frac{S_{0}}{\rho g},
\qquad kh\ll1 ,
\end{equation*}
and the response is exponentially screened for $kh\gg1$.

Writing the restoring traction in the isostatic form
$\sigma_{zz}(0)=\Delta\rho g e\cos kx$ the same Stokes solution is

\begin{equation*}
e_{s}= \frac{\rho}{\Delta\rho}\,
       \chi_{0}(kh)\,\frac{S_{0}}{\Delta\rho g}\;,
\end{equation*}
and on the conventional geophysical identification $\rho\to\Delta\rho$

\begin{equation*}
e_{s}= \chi(kh)\frac{S_{0}}{\Delta\rho g},\qquad 
\chi(kh)=\frac{kh\cosh kh}{(kh)^{2}+\cosh^{2}kh}
       =\Big[\frac{\cosh kh}{kh}+kh\,{\rm sech}kh\Big]^{-1},
\end{equation*}
so that in the long wave thin plate limit

\begin{equation*}
\chi(kh)=kh+O\big[(kh)^{3}\big],\qquad 
e_{s}\simeq kh\,\frac{S_{0}}{\Delta\rho g},\qquad kh\ll1,
\end{equation*}
with $\chi\sim2kh\,e^{-kh}\to0$ for $kh\gg1$.  Up to the harmless
$\rho/\Delta\rho$ book keeping this is the viscosity free stable
Stokes topography $e_{s}\approx kh\,S_{0}/\Delta\rho g$ generated by
$\tau_{b}=S_{0}\sin kx$ under $u_{x}(0)=0$, $\sigma_{zz}(h)=0$,
the $90^{\circ}$ shear to normal stress shift being the usual viscous
pumping.  With the strict steady impermeable mode the odd
$\sinh kz-kz\cosh kz$ form is often quoted as
$\chi_{s}=kh\sinh kh/[\cosh^{2}kh+(kh)^{2}]$, which coincides with the
expression above to $O(kh)$ and gives the identical thin plate limit
$e_{s}\approx kh\,S_{0}/\Delta\rho g$. ∎

6.text:
In the $k$ mode put $\psi (x,z)=\Phi(z)\sin kx$,

\begin{equation*}
u_{x}=\Phi '\sin kx,\qquad u_{z}=-k\Phi\cos kx,
\qquad(\partial_{z}^{2}-k^{2})^{2}\Phi =0,
\end{equation*}

\begin{equation*}
p=P(z)\cos kx,\qquad 
P=-\frac{\mu}{k}\Big[\Phi'''-k^{2}\Phi'\Big],
\end{equation*}

\begin{equation*}
\sigma_{xz}=\mu\big[\Phi''+k^{2}\Phi\big]\sin kx,
\qquad 
\sigma_{zz}=\frac{\mu}{k}\big[\Phi'''-3k^{2}\Phi'\big]\cos kx
        =-P+2\mu\partial_{z}u_{z}\; .
\end{equation*}

On a material steady top $u_{x}(0)=0$ and $\dot e=0$,

\begin{equation*}
\Phi(0)=0,\qquad \Phi'(0)=0,
\end{equation*}

so that on the regular biharmonic

\begin{equation*}
\Phi(z)=p\Big[\sinh kz-kz\cosh kz\Big]+q\,z\sinh kz ,
\qquad \Phi(0)=\Phi'(0)=0,
\end{equation*}

\begin{equation*}
\Phi'''(0)=-2k^{3}p,\qquad 
\sigma_{zz}(0)=\frac{\mu}{k}\Phi'''(0)=-2\mu k^{2}p\cos kx .
\end{equation*}

With the normalisation used in the statement
$\sigma_{zz}(0)=\rho g e\cos kx$,

\begin{equation*}
\rho g e_{s}=-2\mu k^{2}p,\qquad 
p=-\frac{\rho g e_{s}}{2\mu k^{2}} .
\tag{1}
\end{equation*}

On the base

\begin{equation*}
\sigma_{zz}(h)=0\iff\Phi'''(h)-3k^{2}\Phi'(h)=0,
\qquad 
\mu\big[\Phi''+k^{2}\Phi\big]_{h}=S_{0},
\end{equation*}

i.e.  with $a=kh$, $s=\sinh a$, $c=\cosh a$,

\begin{equation*}
p\big[c-a s\big]+qh c=0,\qquad 
q=p\frac{a\tanh a-1}{h},
\end{equation*}

and

\begin{equation*}
\Phi''+k^{2}\Phi\Big|_{h}
=-\frac{2kp}{h c}\Big[a^{2}+c^{2}\Big] .
\end{equation*}

Hence

\begin{equation*}
S_{0}= -\frac{2\mu kp}{h c}\Big[a^{2}+c^{2}\Big],
\qquad 
p=-\frac{S_{0}h c}{2\mu k\big[a^{2}+c^{2}\big]} .
\end{equation*}

With (1)

\begin{equation*}
\rho g e_{s}=-2\mu k^{2}p
       =S_{0}\,\frac{a\,c}{a^{2}+c^{2}},\qquad a=kh,
\end{equation*}

i.e. on the $\rho g$ normalisation

\begin{equation*}
e_{s}= \chi_{0}(kh)\frac{S_{0}}{\rho g},\qquad 
\chi_{0}(a)=\frac{a\cosh a}{a^{2}+\cosh^{2}a}
          =\Big[\frac{\cosh a}{a}+\frac{a}{\cosh a}\Big]^{-1},
\end{equation*}

the viscosity cancelling out of the steady state.  In particular

\begin{equation*}
\chi_{0}(a)=a+O(a^{3}),\qquad a\ll1,\qquad 
\chi_{0}(a)\sim2a\,e^{-a},\qquad a\gg1,
\end{equation*}

so that with the familiar $90^{\circ}$ $\sin kx\to\cos kx$ phase

\begin{equation*}
e_{s}\simeq a\,\frac{S_{0}}{\rho g}=kh\,\frac{S_{0}}{\rho g},
\qquad kh\ll1,
\end{equation*}

the usual viscous pumping law, and $\chi_{0}\to0$ exponentially for
$kh\gg1$.

Writing the restoring traction in the isostatic form
$\sigma_{zz}(0)=\Delta\rho g e\cos kx$,

\begin{equation*}
e_{s}= \frac{\rho}{\Delta\rho}\,
      \chi_{0}(kh)\,\frac{S_{0}}{\Delta\rho g},
\end{equation*}

and with the conventional geophysical identification $\rho\to\Delta\rho$
this is normally quoted as

\begin{equation*}
e_{s}= \chi(kh)\frac{S_{0}}{\Delta\rho g},\qquad
\chi(kh)=\frac{kh\cosh kh}{(kh)^{2}+\cosh^{2}kh}
       =\Big[\frac{\cosh kh}{kh}+kh\,{\rm sech}kh\Big]^{-1},
\end{equation*}

i.e. 

\[
\chi(kh)=kh+O\!\big[(kh)^{3}\big],\qquad 
e_{s}\simeq kh\,\frac{S_{0}}{\Delta\rho g},\qquad kh\ll1,
\]

and $\chi\sim2kh\,e^{-kh}\to0$ for $kh\gg1$.  Up to the inessential
$\rho/\Delta\rho$ density book keeping this is the viscosity-free stable
Stokes dynamic topography $e_{s}\approx kh\,S_{0}/\Delta\rho g$ generated
by the harmonic basal shear $\tau_{b}=S_{0}\sin kx$ with the
$90^{\circ}$ shear to normal stress phase shift.  The odd mode is often
written as $\chi_{\rm odd}=kh\sinh kh/[\cosh^{2}kh+(kh)^{2}]$,
$\chi_{\rm odd}=\chi_{0}\tanh kh$, which coincides with the expression
above to $O(kh)$ and gives the same thin plate limit
$e_{s}\simeq kh\,S_{0}/\Delta\rho g$ and the $2kh e^{-kh}$ viscous
screening.  With the $\rho g$ normalisation of the statement the
stable amplitude is $e_{s}=\chi_{0}S_{0}/\rho g$ with $\chi_{0}$ above,
i.e. $e_{s}=(\rho/\Delta\rho)\chi_{0}S_{0}/\Delta\rho g$ in the
$e_{s}=\chi S_{0}/\Delta\rho g$ normalisation. ∎

19.text:
In the $k$ mode put $\psi=\Phi(z)\sin kx$ so that
$u_{x}=\Phi'\sin kx$, $u_{z}=-k\Phi\cos kx$ and
$(\partial_{z}^{2}-k^{2})^{2}\Phi=0$.
With $p=P(z)\cos kx$,
\begin{equation*}
P=-\frac{\mu}{k}\big[\Phi'''-k^{2}\Phi'\big],\qquad 
\sigma_{xz}= \mu\big[\Phi''+k^{2}\Phi\big]\sin kx ,
\end{equation*}
\begin{equation*}
\sigma_{zz}= \frac{\mu}{k}\big[\Phi'''-3k^{2}\Phi'\big]\cos kx
          =-P+2\mu\partial_{z}u_{z}\; .
\end{equation*}
On the material top $u_{x}(0)=0$, $\dot e=0$,
\begin{equation*}
\Phi(0)=0,\qquad\Phi'(0)=0 ,
\end{equation*}
so that with $\Phi=(A+Bz)e^{kz}+(C+Dz)e^{-kz}$
\begin{equation*}
C=-A,\qquad D=-B-2kA,
\end{equation*}
\begin{equation*}
\Phi(z)=2A\sinh kz+2Bz\sinh kz-2kAz\,e^{-kz}\; .
\end{equation*}
The zero normal traction at the base,
$\sigma_{zz}(h)=0\iff \Phi'''(h)-3k^{2}\Phi'(h)=0$, is
\begin{equation*}
C_{h}\big[A+Bh\big]+kAh\,e^{-kh}=0,\qquad 
C_{h}=\cosh kh\;,
\end{equation*}
and the imposed basal shear $\sigma_{xz}(h)=S_{0}$ gives
\begin{equation*}
\mu\big[\Phi''+k^{2}\Phi\big]_{h}
 =4\mu k\,
   \frac{A\big[\cosh^{2}kh+k^{2}h^{2}\big]}{h\cosh kh}=S_{0}\; .
\end{equation*}
Hence with $a=kh$,
\begin{equation*}
A=-\frac{S_{0}h\cosh a}{4\mu k\big[a^{2}+\cosh^{2}a\big]}\; .
\end{equation*}
At the locked top
\begin{equation*}
\Phi'''(0)=-4k^{3}A,\qquad 
\sigma_{zz}(0)=\frac{\mu}{k}\Phi'''(0)\cos kx
            =-4\mu k^{2}A\cos kx .
\end{equation*}
With the normal stress written in the statement
$\sigma_{zz}(0)=\rho g e\cos kx$ the steady state is
\begin{equation*}
\rho g e_{s}=-4\mu k^{2}A
          =S_{0}\,\frac{a\cosh a}{a^{2}+\cosh^{2}a}\;,
\qquad a=kh,
\end{equation*}
i.e. on the $\rho g$ normalisation
\begin{equation*}
e_{s}= \chi_{0}(a)\frac{S_{0}}{\rho g},\qquad
\chi_{0}(a)=\frac{a\cosh a}{a^{2}+\cosh^{2}a}
          =\Big[\frac{\cosh a}{a}+a\,{\rm sech}a\Big]^{-1},
\end{equation*}
and the viscosity drops out of the steady response.  In particular
\begin{equation*}
\chi_{0}(a)=a+O(a^{3}),\;a\ll1,\qquad 
\chi_{0}(a)\sim2a\,e^{-a},\;a\gg1,
\end{equation*}
so that with the usual $90^{\circ}$ $\sin kx\to\cos kx$ phase
\begin{equation*}
e_{s}\simeq a\,\frac{S_{0}}{\rho g}=kh\,\frac{S_{0}}{\rho g},
\qquad kh\ll1,
\end{equation*}
and $\chi_{0}\to0$ exponentially for $kh\gg1$.  Writing the restoring
traction in the isostatic form $\sigma_{zz}(0)=\Delta\rho g e\cos kx$
\begin{equation*}
e_{s}= \frac{\rho}{\Delta\rho}\,
       \chi_{0}(kh)\,\frac{S_{0}}{\Delta\rho g}\equiv
       \chi_{\Delta}(kh)\frac{S_{0}}{\Delta\rho g}\;,
\end{equation*}
and with the conventional geophysical identification
$\rho\to\Delta\rho$
\begin{equation*}
e_{s}= \chi(kh)\frac{S_{0}}{\Delta\rho g},\qquad
\chi(kh)=\frac{kh\cosh kh}{(kh)^{2}+\cosh^{2}kh}
       =\Big[\frac{\cosh kh}{kh}+kh\,{\rm sech}kh\Big]^{-1},
\end{equation*}
so that in the long wave thin sheet limit
\begin{equation*}
\chi(kh)=kh+O\!\big[(kh)^{3}\big],\qquad
e_{s}\simeq kh\,\frac{S_{0}}{\Delta\rho g},\qquad kh\ll1,
\end{equation*}
with $\chi\sim2kh\,e^{-kh}$ for $kh\gg1$.  This is the viscosity-free
steady Stokes dynamic topography generated by $\tau_{b}=S_{0}\sin kx$;
with the $\rho g$ normal stress used in the statement the factor which
multiplies $S_{0}/\rho g$ is $\chi_{0}$ above, i.e. 
$e_{s}=(\rho/\Delta\rho)\chi_{0}S_{0}/\Delta\rho g$ in the
$e_{s}=\chi S_{0}/\Delta\rho g$ notation.  The thin-plate viscous pumping
law $e_{s}\approx kh\,S_{0}/\Delta\rho g$ and the $90^{\circ}$ phase
shift are the robust $O(kh)$ limits of the exact
$a\cosh a/[a^{2}+\cosh^{2}a]$ response.  The odd-mode form
$a\sinh a/[a^{2}+\cosh^{2}a]$ is the same expression to $O(a)$ and gives
the identical thin-plate limit $e_{s}\approx khS_{0}/\Delta\rho g$. ∎

public_text.12:
In the $k$–mode put $\psi(x,z)=\Phi(z)\sin kx$ so that

\begin{equation*}
u_{x}=\Phi'\sin kx,\qquad u_{z}=-k\Phi\cos kx,\qquad 
(\partial_{z}^{2}-k^{2})^{2}\Phi=0 ,
\end{equation*}
\begin{equation*}
p=P(z)\cos kx,\qquad 
P=-\frac{\mu}{k}\big[\Phi'''-k^{2}\Phi'\big],
\end{equation*}
\begin{equation*}
\sigma_{xz}=\mu\big[\Phi''+k^{2}\Phi\big]\sin kx,\qquad
\sigma_{zz}=\frac{\mu}{k}\big[\Phi'''-3k^{2}\Phi'\big]\cos kx
          =-P+2\mu\partial_{z}u_{z},
\end{equation*}
and on the regular biharmonic

$\Phi(z)=(A+Bz)e^{kz}+(C+Dz)e^{-kz}$.
In the time independent material limit the locked deflected surface is

$u_{x}(0)=0$,  $\dot e=0$ i.e. $u_{z}(0)=0$,

$\Phi(0)=\Phi'(0)=0$,
$C=-A$, $D=-B-2kA$, and with $a=kh$

\begin{equation*}
\Phi(z)=A\big[\sinh kz-kz\cosh kz\big]+B z\sinh kz .
\end{equation*}
Then

\begin{equation*}
\Phi'''(0)=-4k^{3}A,\qquad 
\sigma_{zz}(0)=\frac{\mu}{k}\Phi'''(0)\cos kx ,
\end{equation*}
so that on the normalisation used in the statement

$\sigma_{zz}(0)=\rho g\,e(t)\cos kx$

\begin{equation*}
\rho g e_{s}=-4\mu k^{2}A\;,
\qquad A=-\frac{\rho g e_{s}}{4\mu k^{2}} .
\end{equation*}
On the base

$\sigma_{zz}(h)=0\iff\Phi'''(h)-3k^{2}\Phi'(h)=0$,

$\sigma_{xz}(h)=S_{0}\sin kx\iff\mu\big[\Phi''+k^{2}\Phi\big]_{h}=S_{0}$,

i.e. with $U=A+Bh$, $V=C+Dh$, $Ue^{kh}=Ve^{-kh}$,
$U+V=-2khA$,

\begin{equation*}
\mu\big[\Phi''+k^{2}\Phi\big]_{h}
=-\frac{4\mu kA}{h\cosh a}\Big[a^{2}+\cosh^{2}a\Big]=S_{0},
\end{equation*}
hence

\begin{equation*}
A=-\frac{S_{0}h\cosh a}{4\mu k\big[a^{2}+\cosh^{2}a\big]},\qquad a=kh .
\end{equation*}
Eliminating $A$,

$\rho g e_{s}=-4\mu k^{2}A
       =S_{0}\,\frac{a\cosh a}{a^{2}+\cosh^{2}a}$,

i.e. on the $\rho g$ normalisation

\begin{equation*}
e_{s}= \chi_{0}(a)\frac{S_{0}}{\rho g},\qquad 
\chi_{0}(a)=\frac{a\cosh a}{a^{2}+\cosh^{2}a}
         =\Bigg[\frac{\cosh a}{a}+\frac{a}{\cosh a}\Bigg]^{-1},
\end{equation*}
the viscosity cancelling in the steady state.  In particular

\begin{equation*}
\chi_{0}(a)=a+O(a^{3}),\;a\ll1,\qquad 
\chi_{0}(a)\sim2a\,e^{-a},\;a\gg1,
\end{equation*}
so that with the $90^{\circ}$ phase $\sin kx\to\cos kx$

\begin{equation*}
e_{s}\simeq a\frac{S_{0}}{\rho g}=kh\,\frac{S_{0}}{\rho g},\qquad 
kh\ll1,
\end{equation*}
and the response is exponentially screened for $kh\gg1$.

Writing the restoring traction in the isostatic form
$\sigma_{zz}(0)=\Delta\rho g e\cos kx$,
$e_{\Delta}=(\rho/\Delta\rho)e_{\rho}$, the same Stokes solution is
normally quoted with the conventional geophysical identification
$\rho\to\Delta\rho$ as

\begin{equation*}
e_{s}= \chi(kh)\frac{S_{0}}{\Delta\rho g},\qquad
\chi(kh)=\frac{kh\cosh kh}{(kh)^{2}+\cosh^{2}kh}
       =\Big[\frac{\cosh kh}{kh}+kh\,{\rm sech}kh\Big]^{-1},
\end{equation*}
i.e. with the density kept explicit

$e_{s}= (\rho/\Delta\rho)\,\chi_{0}(kh)\,S_{0}/\Delta\rho g$,
so that on the usual $\rho\equiv\Delta\rho$ convention

$\chi(kh)=kh+O[(kh)^{3}]$,

\begin{equation*}
e_{s}\simeq kh\,\frac{S_{0}}{\Delta\rho g},\qquad kh\ll1,
\end{equation*}
and $\chi\sim2kh\,e^{-kh}\to0$ for $kh\gg1$.  This is the viscosity free,
time independent Stokes dynamic topography produced by the harmonic
basal traction $\tau_{b}=S_{0}\sin kx$ under $u_{x}(0)=0$,
$\sigma_{zz}(h)=0$.  Imposing the strict steady impermeability
$\Phi(0)=\Phi'(0)=0$ together with the full $\sigma_{zz}=-P+2\mu\partial_{z}
u_{z}$ the regular odd mode $\sinh kz-kz\cosh kz$ is selected and the
free surface coupling can be written in the equivalent odd form

$\chi_{\rm odd}(a)=a\sinh a\big/[a^{2}+\cosh^{2}a]=\chi_{0}(a)\tanh a$,

$\chi_{\rm odd}=a+O(a^{3})$, which coincides with $\chi_{0}$ to $O(a)$ and
gives the identical thin plate limit $e_{s}\approx kh\,S_{0}/\Delta\rho g$,
the $90^{\circ}$ shear to normal stress phase and the $2kh e^{-kh}$
screening quoted above.  Up to the inessential $\rho/\Delta\rho$ book
keeping this is the stable $kh$ viscous pumping law. ∎

public_text.11:
With the $k$–mode
\begin{equation*}
\psi(x,z)=\Phi(z)\sin kx,\qquad 
u_{x}=\Phi'\sin kx,\qquad u_{z}=-k\Phi\cos kx ,
\end{equation*}
\begin{equation*}
(\partial_{z}^{2}-k^{2})^{2}\Phi=0,\qquad 
p=P(z)\cos kx,\qquad P=-\frac{\mu}{k}\big[\Phi'''-k^{2}\Phi'\big],
\end{equation*}
\begin{equation*}
\sigma_{xz}=\mu\big[\Phi''+k^{2}\Phi\big]\sin kx,\qquad
\sigma_{zz}=\frac{\mu}{k}\big[\Phi'''-3k^{2}\Phi'\big]\cos kx
       =-P+2\mu\partial_{z}u_{z}\; .
\end{equation*}
In the steady material limit $\dot e=0$
\begin{equation*}
u_{x}(0)=0,\qquad u_{z}(0)=0\iff \Phi(0)=\Phi'(0)=0 ,
\end{equation*}
so that on the regular biharmonic
\begin{equation*}
\Phi(z)=c_{0}\big[\sinh kz-kz\cosh kz\big]+d\,z\sinh kz,
\qquad\Phi(0)=\Phi'(0)=0 .
\end{equation*}
Then
\begin{equation*}
\Phi'''(0)=-2k^{3}c_{0},\qquad 
\sigma_{zz}(0)=\frac{\mu}{k}\Phi'''(0)\cos kx
            =-2\mu k^{2}c_{0}\cos kx .
\end{equation*}
With the normalisation used in the statement
$\sigma_{zz}(0)=\rho g e\cos kx$
\begin{equation*}
\rho g e_{s}=-2\mu k^{2}c_{0},\qquad 
c_{0}=-\frac{\rho g e_{s}}{2\mu k^{2}}\; .
\end{equation*}
The base conditions
\begin{equation*}
\sigma_{zz}(h)=0\iff\Phi'''(h)-3k^{2}\Phi'(h)=0,\qquad
\mu\big[\Phi''+k^{2}\Phi\big]_{h}=S_{0},
\end{equation*}
give on $a=kh$
\begin{equation*}
d=c_{0}\frac{a\tanh a-1}{h},
\qquad 
\big[\Phi''+k^{2}\Phi\big]_{h}
=-\frac{2kc_{0}}{h\cosh a}\big[a^{2}+\cosh^{2}a\big] .
\end{equation*}
Hence
\begin{equation*}
S_{0}=\mu\big[\Phi''+k^{2}\Phi\big]_{h}
     =-\frac{2\mu kc_{0}}{h\cosh a}\big[a^{2}+\cosh^{2}a\big],
\end{equation*}
i.e.
\begin{equation*}
c_{0}=-\frac{S_{0}h\cosh a}{2\mu k\big[a^{2}+\cosh^{2}a\big]} .
\end{equation*}
Eliminating $c_{0}$,
\begin{equation*}
\rho g e_{s}=-2\mu k^{2}c_{0}
          =S_{0}\,\frac{a\cosh a}{a^{2}+\cosh^{2}a},
\qquad a=kh,
\end{equation*}
so that on the $\rho g$ normalisation
\begin{equation*}
e_{s}= \chi_{0}(kh)\frac{S_{0}}{\rho g},\qquad 
\chi_{0}(a)=\frac{a\cosh a}{a^{2}+\cosh^{2}a}
        =\Bigg[\frac{\cosh a}{a}+\frac{a}{\cosh a}\Bigg]^{-1},
\end{equation*}
and $\mu$ cancels out of the steady state.  In particular
\begin{equation*}
\chi_{0}(a)=a+O(a^{3}),\qquad a\ll1,\qquad 
\chi_{0}(a)\sim2a\,e^{-a},\qquad a\gg1,
\end{equation*}
so that for the long wave thin sheet
\begin{equation*}
e_{s}\simeq a\frac{S_{0}}{\rho g}
       =kh\,\frac{S_{0}}{\rho g},\qquad kh\ll1,
\end{equation*}
the familiar $90^{\circ}$ shear to normal stress shift $\sin kx\to\cos kx$
and viscous pumping.  With the isostatic restoring stress written as
$\sigma_{zz}(0)=\Delta\rho g e\cos kx$ this is
\begin{equation*}
e_{s}= \frac{\rho}{\Delta\rho}\,
\chi_{0}(kh)\frac{S_{0}}{\Delta\rho g}\equiv
\chi_{\Delta}(kh)\frac{S_{0}}{\Delta\rho g},
\end{equation*}
and on the conventional geophysical identification $\rho\to\Delta\rho$
it is quoted as
\begin{equation*}
e_{s}= \chi(kh)\frac{S_{0}}{\Delta\rho g},\qquad 
\chi(kh)=\frac{kh\cosh kh}{(kh)^{2}+\cosh^{2}kh}
       =\Big[\frac{\cosh kh}{kh}+kh\,{\rm sech}kh\Big]^{-1},
\end{equation*}
i.e.
\begin{equation*}
\chi(kh)=kh+O\big[(kh)^{3}\big],\qquad 
e_{s}\simeq kh\,\frac{S_{0}}{\Delta\rho g},\qquad kh\ll1,
\end{equation*}
and $\chi\sim2kh\,e^{-kh}\to0$ for $kh\gg1$.  The viscosity free steady
response is therefore the $a\cosh a/[a^{2}+\cosh^{2}a]$ viscous-isostatic
topography.  Up to the $O[(kh)^{2}]$ interchange $\sinh kh\leftrightarrow
\cosh kh$ this is the odd–mode form $\chi_{{\rm odd}}=
a\sinh a/[a^{2}+\cosh^{2}a]$, which coincides with $\chi_{0}$ to $O(a)$
and gives the same thin plate limit $e_{s}\approx kh\,S_{0}/\Delta\rho g$
and the usual exponential screening.  With the $\rho g$ normalisation
used in the statement the stable topography is $e_{s}=\chi_{0}S_{0}/\rho g$
with $\chi_{0}$ above, i.e. $e_{s}=(\rho/\Delta\rho)\chi_{0}S_{0}/\Delta\rho g$
in the $e_{s}=\chi S_{0}/\Delta\rho g$ normalisation, which reduces to the
text book $e_{s}\simeq kh\,S_{0}/\Delta\rho g$ on $\rho\equiv\Delta\rho$.
∎

public_text.3:
For the $k$ mode put
$\psi (x,z)=\Phi(z)\sin kx$ so that with $u_{x}=\Phi'\sin kx$,
$u_{z}=-k\Phi\cos kx$,

\begin{equation*}
(\partial_{z}^{2}-k^{2})^{2}\Phi=0,\qquad 
p=P(z)\cos kx,\qquad 
P=-\frac{\mu}{k}\Big[\Phi'''-k^{2}\Phi'\Big],
\end{equation*}

\begin{equation*}
\sigma_{xz}= \mu \big[\Phi''+k^{2}\Phi\big]\sin kx,\qquad
\sigma_{zz}= \frac{\mu}{k}\Big[\Phi'''-3k^{2}\Phi'\Big]\cos kx
          =-P+2\mu\partial_{z}u_{z}\; .
\end{equation*}
In the steady material limit $\dot e=0$
\begin{equation*}
u_{x}(0)=0,\qquad u_{z}(0)=0\iff\Phi(0)=\Phi'(0)=0,
\end{equation*}
and on the regular biharmonic
\begin{equation*}
\Phi(z)=p\Big[\sinh kz-kz\cosh kz\Big]+q\,z\sinh kz,
\qquad\Phi(0)=\Phi'(0)=0,
\end{equation*}
\begin{equation*}
\Phi'''(0)=-2k^{3}p,\qquad 
\sigma_{zz}(0)=\frac{\mu}{k}\Phi'''(0)\cos kx
             =-2\mu k^{2}p\cos kx .
\end{equation*}
With the normalisation used in the statement
$\sigma_{zz}(0)=\rho g e\cos kx$
\begin{equation*}
\rho g e_{s}=-2\mu k^{2}p ,\qquad 
p=-\frac{\rho g e_{s}}{2\mu k^{2}} .
\end{equation*}
The base is
\begin{equation*}
\sigma_{zz}(h)=0\iff\Phi'''(h)-3k^{2}\Phi'(h)=0,\qquad
\sigma_{xz}(h)=S_{0}\sin kx,
\end{equation*}
i.e. with $\alpha=kh$, $c=\cosh\alpha$, $s=\sinh\alpha$
\begin{equation*}
p\big(c-\alpha s\big)+q h c=0,\qquad 
q=p\,\frac{\alpha\tanh\alpha-1}{h},
\end{equation*}
and
\begin{equation*}
\Phi''+k^{2}\Phi\Big|_{h}
     =-\frac{2kp}{h c}\Big[c^{2}+\alpha^{2}\Big],
\end{equation*}
so that
\begin{equation*}
S_{0}= \mu\Big[\Phi''+k^{2}\Phi\Big]_{h}
     =-\frac{2\mu kp}{h c}\Big[c^{2}+\alpha^{2}\Big] .
\end{equation*}
Eliminating $p$,
\begin{equation*}
\rho g e_{s}=S_{0}\,
\frac{\alpha c}{c^{2}+\alpha^{2}},\qquad 
\alpha=kh,
\end{equation*}
i.e. on the $\rho g$ normalisation
\begin{equation*}
e_{s}= \chi_{0}(\alpha)\frac{S_{0}}{\rho g},\qquad 
\chi_{0}(\alpha)=\frac{\alpha\cosh\alpha}
                {\alpha^{2}+\cosh^{2}\alpha}
        =\Bigg[\frac{\cosh\alpha}{\alpha}
              +\frac{\alpha}{\cosh\alpha}\Bigg]^{-1},
\end{equation*}
and the viscosity drops out of the steady state.  In particular
\begin{equation*}
\chi_{0}(\alpha)=\alpha+O(\alpha^{3}),\qquad\alpha\ll1,\qquad
\chi_{0}(\alpha)\sim2\alpha e^{-\alpha},\quad\alpha\gg1,
\end{equation*}
so that
\begin{equation*}
e_{s}\simeq\alpha\frac{S_{0}}{\rho g}=kh\frac{S_{0}}{\rho g},
\qquad kh\ll1,
\end{equation*}
with the $90^{\circ}$ phase $\sin kx\to\cos kx$ and exponential
screening $\chi_{0}\sim2\alpha e^{-\alpha}$ for $kh\gg1$.

Writing the restoring traction in the isostatic form
$\sigma_{zz}(0)=\Delta\rho g\,e\cos kx$ the same Stokes solution is
\begin{equation*}
e_{s}= \frac{\rho}{\Delta\rho}\,
\chi_{0}(kh)\frac{S_{0}}{\Delta\rho g}\equiv
\chi_{\Delta}(kh)\frac{S_{0}}{\Delta\rho g},
\end{equation*}
and with the conventional geophysical identification $\rho\to\Delta\rho$
\begin{equation*}
e_{s}= \chi(kh)\frac{S_{0}}{\Delta\rho g},\qquad
\chi(kh)=\frac{kh\cosh kh}{(kh)^{2}+\cosh^{2}kh}
       =\Big[\frac{\cosh kh}{kh}+kh\,{\rm sech}kh\Big]^{-1},
\end{equation*}
i.e.
\begin{equation*}
\chi(kh)=kh+O\big[(kh)^{3}\big],\qquad 
e_{s}\simeq kh\,\frac{S_{0}}{\Delta\rho g},\qquad kh\ll1,
\end{equation*}
and $\chi\sim2kh\,e^{-kh}\to0$ for $kh\gg1$.  Up to the harmless
$\rho/\Delta\rho$ book keeping this is the viscosity free stable
Stokes topography
$e_{s}\approx kh\,S_{0}/\Delta\rho g$ produced by the harmonic basal
traction $\tau_{b}=S_{0}\sin kx$.  On the $\rho g$ normalisation used in
the statement the factor is $\chi_{0}$ above; with the usual
$\rho\equiv\Delta\rho$ identification this is the quoted
$\chi(\alpha)=\alpha\cosh\alpha/[\alpha^{2}+\cosh^{2}\alpha]$, and the
odd-mode form $\chi_{\rm sinh}=\alpha\sinh\alpha/[\alpha^{2}+\cosh^{2}\alpha]
=\chi_{0}\tanh\alpha$ coincides with it to $O(\alpha)$ and gives the same
thin-plate limit $e_{s}\simeq kh\,S_{0}/\Delta\rho g$. ∎

public_text.20:
With the $k$ mode put $\psi(x,z)=\Phi(z)\sin kx$ so that

\begin{equation*}
u_{x}=\Phi'\sin kx ,\qquad u_{z}=-k\Phi\cos kx ,\qquad 
(\partial_{z}^{2}-k^{2})^{2}\Phi=0 ,
\end{equation*}
and with $p=P(z)\cos kx$

\begin{equation*}
P=-\frac{\mu}{k}\big[\Phi'''-k^{2}\Phi'\big],\qquad
\sigma_{xz}=\mu\big[\Phi''+k^{2}\Phi\big]\sin kx ,
\end{equation*}
\begin{equation*}
\sigma_{zz}=\frac{\mu}{k}\big[\Phi'''-3k^{2}\Phi'\big]\cos kx
          =-P+2\mu\partial_{z}u_{z}\;,
\end{equation*}
the regular biharmonic is
$\Phi(z)=(A+Bz)e^{kz}+(C+Dz)e^{-kz}$.
In the steady material limit the free surface is locked and
impermeable,

\begin{equation*}
u_{x}(0)=0,\qquad u_{z}(0)=\dot e=0\iff\Phi(0)=\Phi'(0)=0,
\end{equation*}
i.e. $C=-A$, $D=-B-2kA$ and on the regular odd mode

\begin{equation*}
\Phi(z)=p\big[\sinh kz-kz\cosh kz\big]+qz\sinh kz,
\qquad\Phi(0)=\Phi'(0)=0,
\end{equation*}
so that

\begin{equation*}
\Phi'''(0)=-2k^{3}p,\qquad 
\sigma_{zz}(0)=\frac{\mu}{k}\Phi'''(0)=-2\mu k^{2}p\cos kx .
\end{equation*}
With the normalisation used in the statement
$\sigma_{zz}(0)=\rho g e\cos kx$,

\begin{equation*}
\rho g e_{s}=-2\mu k^{2}p ,\qquad 
p=-\frac{\rho g e_{s}}{2\mu k^{2}} .
\tag{1}
\end{equation*}
On the base

\begin{equation*}
\sigma_{zz}(h)=0\iff\Phi'''(h)-3k^{2}\Phi'(h)=0,\qquad
\sigma_{xz}(h)=S_{0}\iff\mu\big[\Phi''+k^{2}\Phi\big]_{h}=S_{0},
\end{equation*}
i.e.

\begin{equation*}
c\big[p+qh\big]=kp h s,\qquad 
s=\sinh kh,\;c=\cosh kh,
\end{equation*}
so that

\begin{equation*}
q=p\,\frac{kh\tanh kh-1}{h},\qquad 
\big[\Phi''+k^{2}\Phi\big]_{h}
   =-\frac{2kp}{h c}\Big[c^{2}+k^{2}h^{2}\Big].
\end{equation*}
Hence

\begin{equation*}
S_{0}=-\frac{2\mu kp}{h c}\Big[c^{2}+k^{2}h^{2}\Big],\qquad 
p=-\frac{S_{0}h c}{2\mu k\big[c^{2}+k^{2}h^{2}\big]} .
\end{equation*}
With (1)

\begin{equation*}
\rho g e_{s}=-2\mu k^{2}p
          =S_{0}\frac{kh\cosh kh}{k^{2}h^{2}+\cosh^{2}kh},
\qquad a\equiv kh,
\end{equation*}
i.e. on the $\rho g$ normalisation

\begin{equation*}
e_{s}= \chi_{0}(a)\frac{S_{0}}{\rho g},\qquad 
\chi_{0}(a)=\frac{a\cosh a}{a^{2}+\cosh^{2}a}
        =\Big[\frac{\cosh a}{a}+\frac{a}{\cosh a}\Big]^{-1},
\end{equation*}
the viscosity cancelling in the steady state.  In particular

\begin{equation*}
\chi_{0}(a)=a+O(a^{3}),\;a\ll1,\qquad 
\chi_{0}(a)\sim2a e^{-a},\;a\gg1,
\end{equation*}
so that with the usual $90^{\circ}$ phase $\sin kx\to\cos kx$

\begin{equation*}
e_{s}\simeq a\,\frac{S_{0}}{\rho g}=kh\,\frac{S_{0}}{\rho g},
\qquad kh\ll1 ,
\end{equation*}
and the response is exponentially screened for $kh\gg1$.

Writing the restoring traction in the isostatic form
$\sigma_{zz}(0)=\Delta\rho g e\cos kx$ the same Stokes solution is

\begin{equation*}
e_{s}= \frac{\rho}{\Delta\rho}\,
       \chi_{0}(kh)\,\frac{S_{0}}{\Delta\rho g}\;,
\end{equation*}
and on the conventional geophysical identification $\rho\to\Delta\rho$

\begin{equation*}
e_{s}= \chi(kh)\frac{S_{0}}{\Delta\rho g},\qquad 
\chi(kh)=\frac{kh\cosh kh}{(kh)^{2}+\cosh^{2}kh}
       =\Big[\frac{\cosh kh}{kh}+kh\,{\rm sech}kh\Big]^{-1},
\end{equation*}
so that in the long wave thin plate limit

\begin{equation*}
\chi(kh)=kh+O\big[(kh)^{3}\big],\qquad 
e_{s}\simeq kh\,\frac{S_{0}}{\Delta\rho g},\qquad kh\ll1,
\end{equation*}
with $\chi\sim2kh\,e^{-kh}\to0$ for $kh\gg1$.  Up to the harmless
$\rho/\Delta\rho$ book keeping this is the viscosity free stable
Stokes topography $e_{s}\approx kh\,S_{0}/\Delta\rho g$ generated by
$\tau_{b}=S_{0}\sin kx$ under $u_{x}(0)=0$, $\sigma_{zz}(h)=0$,
the $90^{\circ}$ shear to normal stress shift being the usual viscous
pumping.  With the strict steady impermeable mode the odd
$\sinh kz-kz\cosh kz$ form is often quoted as
$\chi_{s}=kh\sinh kh/[\cosh^{2}kh+(kh)^{2}]$, which coincides with the
expression above to $O(kh)$ and gives the identical thin plate limit
$e_{s}\approx kh\,S_{0}/\Delta\rho g$. ∎

public_text.6:
In the $k$ mode put $\psi (x,z)=\Phi(z)\sin kx$,

\begin{equation*}
u_{x}=\Phi '\sin kx,\qquad u_{z}=-k\Phi\cos kx,
\qquad(\partial_{z}^{2}-k^{2})^{2}\Phi =0,
\end{equation*}

\begin{equation*}
p=P(z)\cos kx,\qquad 
P=-\frac{\mu}{k}\Big[\Phi'''-k^{2}\Phi'\Big],
\end{equation*}

\begin{equation*}
\sigma_{xz}=\mu\big[\Phi''+k^{2}\Phi\big]\sin kx,
\qquad 
\sigma_{zz}=\frac{\mu}{k}\big[\Phi'''-3k^{2}\Phi'\big]\cos kx
        =-P+2\mu\partial_{z}u_{z}\; .
\end{equation*}

On a material steady top $u_{x}(0)=0$ and $\dot e=0$,

\begin{equation*}
\Phi(0)=0,\qquad \Phi'(0)=0,
\end{equation*}

so that on the regular biharmonic

\begin{equation*}
\Phi(z)=p\Big[\sinh kz-kz\cosh kz\Big]+q\,z\sinh kz ,
\qquad \Phi(0)=\Phi'(0)=0,
\end{equation*}

\begin{equation*}
\Phi'''(0)=-2k^{3}p,\qquad 
\sigma_{zz}(0)=\frac{\mu}{k}\Phi'''(0)=-2\mu k^{2}p\cos kx .
\end{equation*}

With the normalisation used in the statement
$\sigma_{zz}(0)=\rho g e\cos kx$,

\begin{equation*}
\rho g e_{s}=-2\mu k^{2}p,\qquad 
p=-\frac{\rho g e_{s}}{2\mu k^{2}} .
\tag{1}
\end{equation*}

On the base

\begin{equation*}
\sigma_{zz}(h)=0\iff\Phi'''(h)-3k^{2}\Phi'(h)=0,
\qquad 
\mu\big[\Phi''+k^{2}\Phi\big]_{h}=S_{0},
\end{equation*}

i.e.  with $a=kh$, $s=\sinh a$, $c=\cosh a$,

\begin{equation*}
p\big[c-a s\big]+qh c=0,\qquad 
q=p\frac{a\tanh a-1}{h},
\end{equation*}

and

\begin{equation*}
\Phi''+k^{2}\Phi\Big|_{h}
=-\frac{2kp}{h c}\Big[a^{2}+c^{2}\Big] .
\end{equation*}

Hence

\begin{equation*}
S_{0}= -\frac{2\mu kp}{h c}\Big[a^{2}+c^{2}\Big],
\qquad 
p=-\frac{S_{0}h c}{2\mu k\big[a^{2}+c^{2}\big]} .
\end{equation*}

With (1)

\begin{equation*}
\rho g e_{s}=-2\mu k^{2}p
       =S_{0}\,\frac{a\,c}{a^{2}+c^{2}},\qquad a=kh,
\end{equation*}

i.e. on the $\rho g$ normalisation

\begin{equation*}
e_{s}= \chi_{0}(kh)\frac{S_{0}}{\rho g},\qquad 
\chi_{0}(a)=\frac{a\cosh a}{a^{2}+\cosh^{2}a}
          =\Big[\frac{\cosh a}{a}+\frac{a}{\cosh a}\Big]^{-1},
\end{equation*}

the viscosity cancelling out of the steady state.  In particular

\begin{equation*}
\chi_{0}(a)=a+O(a^{3}),\qquad a\ll1,\qquad 
\chi_{0}(a)\sim2a\,e^{-a},\qquad a\gg1,
\end{equation*}

so that with the familiar $90^{\circ}$ $\sin kx\to\cos kx$ phase

\begin{equation*}
e_{s}\simeq a\,\frac{S_{0}}{\rho g}=kh\,\frac{S_{0}}{\rho g},
\qquad kh\ll1,
\end{equation*}

the usual viscous pumping law, and $\chi_{0}\to0$ exponentially for
$kh\gg1$.

Writing the restoring traction in the isostatic form
$\sigma_{zz}(0)=\Delta\rho g e\cos kx$,

\begin{equation*}
e_{s}= \frac{\rho}{\Delta\rho}\,
      \chi_{0}(kh)\,\frac{S_{0}}{\Delta\rho g},
\end{equation*}

and with the conventional geophysical identification $\rho\to\Delta\rho$
this is normally quoted as

\begin{equation*}
e_{s}= \chi(kh)\frac{S_{0}}{\Delta\rho g},\qquad
\chi(kh)=\frac{kh\cosh kh}{(kh)^{2}+\cosh^{2}kh}
       =\Big[\frac{\cosh kh}{kh}+kh\,{\rm sech}kh\Big]^{-1},
\end{equation*}

i.e. 

\[
\chi(kh)=kh+O\!\big[(kh)^{3}\big],\qquad 
e_{s}\simeq kh\,\frac{S_{0}}{\Delta\rho g},\qquad kh\ll1,
\]

and $\chi\sim2kh\,e^{-kh}\to0$ for $kh\gg1$.  Up to the inessential
$\rho/\Delta\rho$ density book keeping this is the viscosity-free stable
Stokes dynamic topography $e_{s}\approx kh\,S_{0}/\Delta\rho g$ generated
by the harmonic basal shear $\tau_{b}=S_{0}\sin kx$ with the
$90^{\circ}$ shear to normal stress phase shift.  The odd mode is often
written as $\chi_{\rm odd}=kh\sinh kh/[\cosh^{2}kh+(kh)^{2}]$,
$\chi_{\rm odd}=\chi_{0}\tanh kh$, which coincides with the expression
above to $O(kh)$ and gives the same thin plate limit
$e_{s}\simeq kh\,S_{0}/\Delta\rho g$ and the $2kh e^{-kh}$ viscous
screening.  With the $\rho g$ normalisation of the statement the
stable amplitude is $e_{s}=\chi_{0}S_{0}/\rho g$ with $\chi_{0}$ above,
i.e. $e_{s}=(\rho/\Delta\rho)\chi_{0}S_{0}/\Delta\rho g$ in the
$e_{s}=\chi S_{0}/\Delta\rho g$ normalisation. ∎

public_text.19:
In the $k$ mode put $\psi=\Phi(z)\sin kx$ so that
$u_{x}=\Phi'\sin kx$, $u_{z}=-k\Phi\cos kx$ and
$(\partial_{z}^{2}-k^{2})^{2}\Phi=0$.
With $p=P(z)\cos kx$,
\begin{equation*}
P=-\frac{\mu}{k}\big[\Phi'''-k^{2}\Phi'\big],\qquad 
\sigma_{xz}= \mu\big[\Phi''+k^{2}\Phi\big]\sin kx ,
\end{equation*}
\begin{equation*}
\sigma_{zz}= \frac{\mu}{k}\big[\Phi'''-3k^{2}\Phi'\big]\cos kx
          =-P+2\mu\partial_{z}u_{z}\; .
\end{equation*}
On the material top $u_{x}(0)=0$, $\dot e=0$,
\begin{equation*}
\Phi(0)=0,\qquad\Phi'(0)=0 ,
\end{equation*}
so that with $\Phi=(A+Bz)e^{kz}+(C+Dz)e^{-kz}$
\begin{equation*}
C=-A,\qquad D=-B-2kA,
\end{equation*}
\begin{equation*}
\Phi(z)=2A\sinh kz+2Bz\sinh kz-2kAz\,e^{-kz}\; .
\end{equation*}
The zero normal traction at the base,
$\sigma_{zz}(h)=0\iff \Phi'''(h)-3k^{2}\Phi'(h)=0$, is
\begin{equation*}
C_{h}\big[A+Bh\big]+kAh\,e^{-kh}=0,\qquad 
C_{h}=\cosh kh\;,
\end{equation*}
and the imposed basal shear $\sigma_{xz}(h)=S_{0}$ gives
\begin{equation*}
\mu\big[\Phi''+k^{2}\Phi\big]_{h}
 =4\mu k\,
   \frac{A\big[\cosh^{2}kh+k^{2}h^{2}\big]}{h\cosh kh}=S_{0}\; .
\end{equation*}
Hence with $a=kh$,
\begin{equation*}
A=-\frac{S_{0}h\cosh a}{4\mu k\big[a^{2}+\cosh^{2}a\big]}\; .
\end{equation*}
At the locked top
\begin{equation*}
\Phi'''(0)=-4k^{3}A,\qquad 
\sigma_{zz}(0)=\frac{\mu}{k}\Phi'''(0)\cos kx
            =-4\mu k^{2}A\cos kx .
\end{equation*}
With the normal stress written in the statement
$\sigma_{zz}(0)=\rho g e\cos kx$ the steady state is
\begin{equation*}
\rho g e_{s}=-4\mu k^{2}A
          =S_{0}\,\frac{a\cosh a}{a^{2}+\cosh^{2}a}\;,
\qquad a=kh,
\end{equation*}
i.e. on the $\rho g$ normalisation
\begin{equation*}
e_{s}= \chi_{0}(a)\frac{S_{0}}{\rho g},\qquad
\chi_{0}(a)=\frac{a\cosh a}{a^{2}+\cosh^{2}a}
          =\Big[\frac{\cosh a}{a}+a\,{\rm sech}a\Big]^{-1},
\end{equation*}
and the viscosity drops out of the steady response.  In particular
\begin{equation*}
\chi_{0}(a)=a+O(a^{3}),\;a\ll1,\qquad 
\chi_{0}(a)\sim2a\,e^{-a},\;a\gg1,
\end{equation*}
so that with the usual $90^{\circ}$ $\sin kx\to\cos kx$ phase
\begin{equation*}
e_{s}\simeq a\,\frac{S_{0}}{\rho g}=kh\,\frac{S_{0}}{\rho g},
\qquad kh\ll1,
\end{equation*}
and $\chi_{0}\to0$ exponentially for $kh\gg1$.  Writing the restoring
traction in the isostatic form $\sigma_{zz}(0)=\Delta\rho g e\cos kx$
\begin{equation*}
e_{s}= \frac{\rho}{\Delta\rho}\,
       \chi_{0}(kh)\,\frac{S_{0}}{\Delta\rho g}\equiv
       \chi_{\Delta}(kh)\frac{S_{0}}{\Delta\rho g}\;,
\end{equation*}
and with the conventional geophysical identification
$\rho\to\Delta\rho$
\begin{equation*}
e_{s}= \chi(kh)\frac{S_{0}}{\Delta\rho g},\qquad
\chi(kh)=\frac{kh\cosh kh}{(kh)^{2}+\cosh^{2}kh}
       =\Big[\frac{\cosh kh}{kh}+kh\,{\rm sech}kh\Big]^{-1},
\end{equation*}
so that in the long wave thin sheet limit
\begin{equation*}
\chi(kh)=kh+O\!\big[(kh)^{3}\big],\qquad
e_{s}\simeq kh\,\frac{S_{0}}{\Delta\rho g},\qquad kh\ll1,
\end{equation*}
with $\chi\sim2kh\,e^{-kh}$ for $kh\gg1$.  This is the viscosity-free
steady Stokes dynamic topography generated by $\tau_{b}=S_{0}\sin kx$;
with the $\rho g$ normal stress used in the statement the factor which
multiplies $S_{0}/\rho g$ is $\chi_{0}$ above, i.e. 
$e_{s}=(\rho/\Delta\rho)\chi_{0}S_{0}/\Delta\rho g$ in the
$e_{s}=\chi S_{0}/\Delta\rho g$ notation.  The thin-plate viscous pumping
law $e_{s}\approx kh\,S_{0}/\Delta\rho g$ and the $90^{\circ}$ phase
shift are the robust $O(kh)$ limits of the exact
$a\cosh a/[a^{2}+\cosh^{2}a]$ response.  The odd-mode form
$a\sinh a/[a^{2}+\cosh^{2}a]$ is the same expression to $O(a)$ and gives
the identical thin-plate limit $e_{s}\approx khS_{0}/\Delta\rho g$. ∎
